  cols=[]
  for x,y in data:
   u=(x-xref)/span; cols.append([u**j for j in range(deg+1)]+[1/(1+((x-xrs)/gr)**2),1/(1+((x-xgs)/gg)**2)])
  return linfit([(x-xref)/span for x,y in data],[y for x,y in data],cols)[1]
 n=4;s=[init[:]]
