  c=[sum(s[i][j] for i in range(n))/n for j in range(n)];r=[2*c[j]-s[-1][j] for j in range(n)];vr=ob(r)
  if v[0]<=vr<v[-2]:s[-1]=r;v[-1]=vr;continue
