   e=[c[j]+2*(r[j]-c[j]) for j in range(n)];ve=ob(e);s[-1],v[-1]=(e,ve) if ve<vr else (r,vr);continue
  co=[c[j]+.5*(s[-1][j]-c[j]) for j in range(n)];vc=ob(co)
  if vc<v[-1]:s[-1]=co;v[-1]=vc;continue
  for i in range(1,n+1):s[i]=[s[0][j]+.5*(s[i][j]-s[0][j]) for j in range(n)];v[i]=ob(s[i])
