def constrained(data,lo0,hi0,glo,ghi,deg=0,xref=0,span=1):
 if xref==0:xref=sum(x for x,y in data)/len(data)
 if span==1:span=max(x for x,y in data)-min(x for x,y in data)
 def f(x0,g):
  us=[(x-xref)/span for x,y in data]; cols=[]
  for (x,y),u in zip(data,us):cols.append([u**j for j in range(deg+1)]+[1/(1+((x-x0)/g)**2)])
  p,s=linfit(us,[y for x,y in data],cols)
  if p[-1]<0:return 1e100,None
  return s,p
 # grid then local coordinate hill search
 best=(1e100,None,None)
 for i in range(101):
  x0=lo0+(hi0-lo0)*i/100
  for j in range(101):
   lg=math.log(glo)+(math.log(ghi)-math.log(glo))*j/100
   g=math.exp(lg);s,p=f(x0,g)
   if s<best[0]:best=(s,x0,g,p)
