  for di in (-2,-1,0,1,2):
   for dj in (-2,-1,0,1,2):
    xx=min(hi0,max(lo0,x0+di*dx));gg=min(ghi,max(glo,g*math.exp(dj*dl)));ss,pp=f(xx,gg);cand.append((ss,xx,gg,pp))
  best=min(cand,key=lambda z:z[0]);s,x0,g,p=best
 return best
