def solve(A,b):
 n=len(b);M=[list(r)+[b[i]] for i,r in enumerate(A)]
 for k in range(n):
  p=max(range(k,n),key=lambda i:abs(M[i][k]));M[k],M[p]=M[p],M[k];q=M[k][k]
  for j in range(k,n+1):M[k][j]/=q
  for i in range(n):
   if i!=k:
    q=M[i][k]
    for j in range(k,n+1):M[i][j]-=q*M[k][j]
 return [M[i][n] for i in range(n)]
def fit(data,bx):
 def calc(x0,g):
  z=[1/(1+((x-x0)/g)**2) for x,y in data]; ys=[y for x,y in data]
  A=[[len(data),sum(z)],[sum(z),sum(v*v for v in z)]];b=[sum(ys),sum(a*c for a,c in zip(z,ys))];p=solve(A,b)
  return sum((p[0]+p[1]*a-y)**2 for (x,y),a in zip(data,z)),p
